import{_ as a,o as t,c as s,a2 as i}from"./chunks/framework.Bg-Zxr5O.js";const m=JSON.parse('{"title":"","description":"","frontmatter":{},"headers":[],"relativePath":"manual-en/DATA-LIST-FREE.md","filePath":"manual-en/DATA-LIST-FREE.md","lastUpdated":1785684581000}'),o={name:"manual-en/DATA-LIST-FREE.md"};function n(r,e,d,l,c,p){return t(),s("div",null,[...e[0]||(e[0]=[i(`<h4 id="_8-5-2-data-list-free" tabindex="-1">8.5.2 DATA LIST FREE <a class="header-anchor" href="#_8-5-2-data-list-free" aria-label="Permalink to &quot;8.5.2 DATA LIST FREE&quot;">​</a></h4><pre><code>DATA LIST FREE
        [({TAB,’c’}, …)]
        [{NOTABLE,TABLE}]
        [FILE=’file_name’ [ENCODING=’encoding’]]
        [SKIP=n_records]
        /var_spec…

where each var_spec takes one of the forms
        var_list [(type_spec)]
        var_list *
</code></pre><p>In free format, the input data is, by default, structured as a series of fields separated by spaces, tabs, or line breaks. If the current <code>DECIMAL</code> separator is <code>DOT</code> (see <a href="./SET">SET</a>), then commas are also treated as field separators. Each field’s content may be unquoted, or it may be quoted with a pairs of apostrophes (‘&#39;’) or double quotes (‘&quot;’). Unquoted white space separates fields but is not part of any field. Any mix of spaces, tabs, and line breaks is equivalent to a single space for the purpose of separating fields, but consecutive commas will skip a field.</p><p>Alternatively, delimiters can be specified explicitly, as a parenthesized, comma-separated list of single-character strings immediately following FREE. The word TAB may also be used to specify a tab character as a delimiter. When delimiters are specified explicitly, only the given characters, plus line breaks, separate fields. Furthermore, leading spaces at the beginnings of fields are not trimmed, consecutive delimiters define empty fields, and no form of quoting is allowed.</p><p>The <code>NOTABLE</code> and <code>TABLE</code> subcommands are as in <code>DATA LIST FIXED</code> above. <code>NOTABLE</code> is the default.</p><p>The <code>FILE</code>, <code>SKIP</code>, and <code>ENCODING</code> subcommands are as in <code>DATA LIST FIXED</code> above.</p><p>The variables to be parsed are given as a single list of variable names. This list must be introduced by a single slash (‘/’). The set of variable names may contain format specifications in parentheses (see <a href="./Input-and-Output-Formats">Input and Output Formats</a>). Format specifications apply to all variables back to the previous parenthesized format specification.</p><p>In addition, an asterisk may be used to indicate that all variables preceding it are to have input/output format ‘F8.0’.</p><p>Specified field widths are ignored on input, although all normal limits on field width apply, but they are honored on output.</p>`,9)])])}const u=a(o,[["render",n]]);export{m as __pageData,u as default};
